import (
	"fmt"
	"sort"
)

// Names of the protocol values are used to build readable errors: KMIP
// failures are otherwise reported as bare hex numbers, which requires the
// spec at hand to make any sense of.

// tagNameMap maps tag value back to the tag name
//
// It is built out of tagMap, so that it covers every tag known to the
// library. Several names might share the same tag value (BATCH_ITEM,
// REQUEST_BATCH_ITEM and RESPONSE_BATCH_ITEM are all 0x42000F), names are
// processed in sorted order and the first one wins to keep the result stable.
var tagNameMap = buildTagNameMap()

func buildTagNameMap() map[Tag]string {
	names := make([]string, 0, len(tagMap))

	for name := range tagMap {
		if name == "-" {
			// alias for ANY_TAG used in Go struct tags
			continue
		}

		names = append(names, name)
	}

	sort.Strings(names)

	res := make(map[Tag]string, len(names))

	for _, name := range names {
		if _, ok := res[tagMap[name]]; !ok {
			res[tagMap[name]] = name
		}
	}

	return res
}

