// TagName returns tag name and value as a string, e.g. "OPERATION (0x42005c)"
func TagName(t Tag) string {
	if name, ok := tagNameMap[t]; ok {
		return fmt.Sprintf("%s (0x%06x)", name, uint32(t))
	}

	return fmt.Sprintf("unknown tag (0x%06x)", uint32(t))
}

// TypeName returns type name and value as a string, e.g. "ENUMERATION (0x05)"
func TypeName(t Type) string {
	if name, ok := typeNameMap[t]; ok {
		return fmt.Sprintf("%s (0x%02x)", name, uint8(t))
	}

	return fmt.Sprintf("unknown type (0x%02x)", uint8(t))
}

// OperationName returns name of the operation, e.g. "OPERATION_ENCRYPT"
func OperationName(operation Enum) string {
	return enumName(operationMap, operation, "operation")
}

// ResultStatusName returns name of the result status,
// e.g. "RESULT_STATUS_OPERATION_FAILED"
func ResultStatusName(status Enum) string {
	return enumName(resultStatusMap, status, "result status")
}

// ResultReasonName returns name of the result reason,
// e.g. "RESULT_REASON_ITEM_NOT_FOUND"
func ResultReasonName(reason Enum) string {
	return enumName(resultReasonMap, reason, "result reason")
}

func enumName(names map[Enum]string, value Enum, what string) string {
	if name, ok := names[value]; ok {
		return name
	}

	return fmt.Sprintf("unknown %s (0x%08x)", what, uint32(value))
}
